drop extension if exists "pg_net";

create type "public"."event_role_enum" as enum ('Host', 'Participant');

create type "public"."invitation_status_enum" as enum ('Pending', 'Accepted', 'Declined');

create sequence "public"."event_event_id_seq";

create sequence "public"."event_participation_event_participation_id_seq";

create sequence "public"."location_location_id_seq";

create sequence "public"."person_person_id_seq";


  create table "public"."event" (
    "event_id" integer generated by default as identity not null,
    "title" character varying(255) not null,
    "date" timestamp without time zone not null,
    "description" text,
    "location_id" integer not null,
    "invitation_link" character varying(255) not null,
    "created_at" timestamp without time zone default CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone default CURRENT_TIMESTAMP,
    "is_public" boolean not null default false,
    "max_capacity" numeric,
    "category" text
      );



  create table "public"."event_media" (
    "media_url" text not null,
    "uploaded_at" timestamp with time zone default now(),
    "uploader_id" integer not null,
    "event_id" integer not null
      );


alter table "public"."event_media" enable row level security;


  create table "public"."event_participation" (
    "event_participation_id" integer generated by default as identity not null,
    "person_id" integer not null,
    "event_id" integer not null,
    "role" public.event_role_enum not null,
    "created_at" timestamp without time zone default CURRENT_TIMESTAMP
      );



  create table "public"."location" (
    "location_id" integer generated by default as identity not null,
    "street" character varying(255) not null,
    "house_number" character varying(20) not null,
    "postal_code" character varying(10) not null,
    "city" character varying(100) not null,
    "country" character varying(100) not null,
    "size" integer,
    "type" character varying(100),
    "description" text,
    "created_at" timestamp without time zone default CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone default CURRENT_TIMESTAMP
      );



  create table "public"."participation" (
    "event_participation_id" integer not null,
    "status" public.invitation_status_enum default 'Pending'::public.invitation_status_enum,
    "task_description" text,
    "created_at" timestamp without time zone default CURRENT_TIMESTAMP
      );



  create table "public"."person" (
    "person_id" integer generated by default as identity not null,
    "phone_number" character varying(50),
    "email_address" character varying(255),
    "created_at" timestamp without time zone default CURRENT_TIMESTAMP,
    "updated_at" timestamp without time zone default CURRENT_TIMESTAMP,
    "first_name" text not null,
    "last_name" text
      );


alter table "public"."person" enable row level security;


  create table "public"."ticket" (
    "ticket_number" character varying(100) not null,
    "price" numeric(10,2) not null default 0.00,
    "issued_at" timestamp without time zone not null default CURRENT_TIMESTAMP,
    "redeemed_at" timestamp without time zone,
    "qr_code_link" text not null,
    "event_participation_id" integer not null,
    "multiple_use" boolean not null default false,
    "scan_count" numeric not null default '0'::numeric
      );


alter sequence "public"."event_event_id_seq" owned by "public"."event"."event_id";

alter sequence "public"."event_participation_event_participation_id_seq" owned by "public"."event_participation"."event_participation_id";

alter sequence "public"."location_location_id_seq" owned by "public"."location"."location_id";

alter sequence "public"."person_person_id_seq" owned by "public"."person"."person_id";

CREATE UNIQUE INDEX event_invitation_link_key ON public.event USING btree (invitation_link);

CREATE UNIQUE INDEX event_media_pkey ON public.event_media USING btree (media_url);

CREATE UNIQUE INDEX event_participation_pkey ON public.event_participation USING btree (event_participation_id);

CREATE UNIQUE INDEX event_pkey ON public.event USING btree (event_id);

CREATE INDEX idx_event_date ON public.event USING btree (date);

CREATE INDEX idx_event_location ON public.event USING btree (location_id);

CREATE INDEX idx_event_participation_event ON public.event_participation USING btree (event_id);

CREATE INDEX idx_event_participation_person ON public.event_participation USING btree (person_id);

CREATE INDEX idx_event_participation_role ON public.event_participation USING btree (role);

CREATE INDEX idx_participation_event_participation ON public.participation USING btree (event_participation_id);

CREATE INDEX idx_participation_status ON public.participation USING btree (status);

CREATE INDEX idx_person_email ON public.person USING btree (email_address);

CREATE INDEX idx_person_phone ON public.person USING btree (phone_number);

CREATE INDEX idx_ticket_participation ON public.ticket USING btree (event_participation_id);

CREATE UNIQUE INDEX location_pkey ON public.location USING btree (location_id);

CREATE UNIQUE INDEX participation_event_participation_id_key ON public.participation USING btree (event_participation_id);

CREATE UNIQUE INDEX participation_pkey ON public.participation USING btree (event_participation_id);

CREATE UNIQUE INDEX person_email_address_key ON public.person USING btree (email_address);

CREATE UNIQUE INDEX person_phone_number_key ON public.person USING btree (phone_number);

CREATE UNIQUE INDEX person_pkey ON public.person USING btree (person_id);

CREATE UNIQUE INDEX ticket_pkey ON public.ticket USING btree (ticket_number);

CREATE UNIQUE INDEX unique_person_event ON public.event_participation USING btree (person_id, event_id);

alter table "public"."event" add constraint "event_pkey" PRIMARY KEY using index "event_pkey";

alter table "public"."event_media" add constraint "event_media_pkey" PRIMARY KEY using index "event_media_pkey";

alter table "public"."event_participation" add constraint "event_participation_pkey" PRIMARY KEY using index "event_participation_pkey";

alter table "public"."location" add constraint "location_pkey" PRIMARY KEY using index "location_pkey";

alter table "public"."participation" add constraint "participation_pkey" PRIMARY KEY using index "participation_pkey";

alter table "public"."person" add constraint "person_pkey" PRIMARY KEY using index "person_pkey";

alter table "public"."ticket" add constraint "ticket_pkey" PRIMARY KEY using index "ticket_pkey";

alter table "public"."event" add constraint "event_invitation_link_key" UNIQUE using index "event_invitation_link_key";

alter table "public"."event" add constraint "event_location_id_fkey" FOREIGN KEY (location_id) REFERENCES public.location(location_id) not valid;

alter table "public"."event" validate constraint "event_location_id_fkey";

alter table "public"."event_media" add constraint "event_media_event_id_fkey" FOREIGN KEY (event_id) REFERENCES public.event(event_id) ON DELETE CASCADE not valid;

alter table "public"."event_media" validate constraint "event_media_event_id_fkey";

alter table "public"."event_media" add constraint "event_media_uploader_id_fkey" FOREIGN KEY (uploader_id) REFERENCES public.person(person_id) ON DELETE CASCADE not valid;

alter table "public"."event_media" validate constraint "event_media_uploader_id_fkey";

alter table "public"."event_participation" add constraint "event_participation_event_id_fkey" FOREIGN KEY (event_id) REFERENCES public.event(event_id) ON DELETE CASCADE not valid;

alter table "public"."event_participation" validate constraint "event_participation_event_id_fkey";

alter table "public"."event_participation" add constraint "event_participation_person_id_fkey" FOREIGN KEY (person_id) REFERENCES public.person(person_id) ON DELETE CASCADE not valid;

alter table "public"."event_participation" validate constraint "event_participation_person_id_fkey";

alter table "public"."event_participation" add constraint "unique_person_event" UNIQUE using index "unique_person_event";

alter table "public"."participation" add constraint "participation_event_participation_id_fkey" FOREIGN KEY (event_participation_id) REFERENCES public.event_participation(event_participation_id) ON DELETE CASCADE not valid;

alter table "public"."participation" validate constraint "participation_event_participation_id_fkey";

alter table "public"."participation" add constraint "participation_event_participation_id_key" UNIQUE using index "participation_event_participation_id_key";

alter table "public"."person" add constraint "person_email_address_key" UNIQUE using index "person_email_address_key";

alter table "public"."person" add constraint "person_phone_number_key" UNIQUE using index "person_phone_number_key";

alter table "public"."ticket" add constraint "ticket_event_participation_id_fkey" FOREIGN KEY (event_participation_id) REFERENCES public.participation(event_participation_id) ON DELETE CASCADE not valid;

alter table "public"."ticket" validate constraint "ticket_event_participation_id_fkey";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$function$
;

